export default {"G000305":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Possibly noncommutative unital rings · construction · <code>G000305</code></p><h3>Bicommutant of a right module</h3><p>For a right <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span></span>-module <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M</mi></mrow><annotation encoding=\"application/x-tex\">M</annotation></semantics></math></span></span>, put <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E</mi><mo>=</mo><msub><mrow><mi mathvariant=\"normal\">End</mi><mo>⁡</mo></mrow><mi>R</mi></msub><mo stretchy=\"false\">(</mo><mi>M</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">E=\\operatorname{End}_R(M)</annotation></semantics></math></span></span> acting on the left. The bicommutant is <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mrow><mi mathvariant=\"normal\">End</mi><mo>⁡</mo></mrow><mi>E</mi></msub><mo stretchy=\"false\">(</mo><mi>M</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\operatorname{End}_E(M)</annotation></semantics></math></span></span> with ordinary composition; right multiplication defines a map from <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>R</mi><mrow><mi mathvariant=\"normal\">o</mi><mi mathvariant=\"normal\">p</mi></mrow></msup></mrow><annotation encoding=\"application/x-tex\">R^{\\mathrm{op}}</annotation></semantics></math></span></span> to it.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0745\">Stacks 0745 · numbered source and proof</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/brauer/#tag-0745\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#G000305\">Open shared record</a></p></article>","G000309":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Fields · construction · <code>G000309</code></p><h3>Brauer group of a field</h3><p>The underlying set of <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Br</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>k</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">\\operatorname{Br}(k)</annotation></semantics></math></span></span> consists of similarity classes of finite central simple <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span></span>-algebras. Tensor product induces addition.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/074L\">Stacks 074L · numbered source and proof · Stacks 074L · abelian group of similarity classes</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/brauer/#tag-074L\">Index</a> · <a href=\"https://www.jmilne.org/math/CourseNotes/CFT.pdf#page=139\">J. S. Milne, Class Field Theory, IV, definition of the Brauer group and Remark 2.13(a)</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#G000309\">Open shared record</a></p></article>","G000308":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Unital associative algebras over a specified field · construction · <code>G000308</code></p><h3>Brauer similarity</h3><p>For two finite central simple <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span></span>-algebras <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi><mo separator=\"true\">,</mo><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">A,B</annotation></semantics></math></span></span>, similarity means that <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>M</mi><mi>m</mi></msub><mo stretchy=\"false\">(</mo><mi>A</mi><mo stretchy=\"false\">)</mo><mo>≃</mo><msub><mi>M</mi><mi>n</mi></msub><mo stretchy=\"false\">(</mo><mi>B</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">M_m(A)\\simeq M_n(B)</annotation></semantics></math></span></span> as <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span></span>-algebras for some positive integers <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi><mo separator=\"true\">,</mo><mi>n</mi></mrow><annotation encoding=\"application/x-tex\">m,n</annotation></semantics></math></span></span>.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/074K\">Stacks 074K · numbered source and proof · Stacks 074K · similarity used in (1)–(3)</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/brauer/#tag-074K\">Index</a> · <a href=\"https://www.jmilne.org/math/CourseNotes/CFT.pdf#page=139\">J. S. Milne, Class Field Theory, IV, definition of the Brauer group and Remark 2.13(a)</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#G000308\">Open shared record</a></p></article>","G000306":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Unital associative algebras over a specified field · construction · <code>G000306</code></p><h3>Centralizer of a subalgebra</h3><p>For a unital <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi></mrow><annotation encoding=\"application/x-tex\">k</annotation></semantics></math></span></span>-subalgebra <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B</mi><mo>⊆</mo><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">B\\subseteq A</annotation></semantics></math></span></span>, its centralizer <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C</mi><mi>A</mi></msub><mo stretchy=\"false\">(</mo><mi>B</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">C_A(B)</annotation></semantics></math></span></span> consists of all <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mo>∈</mo><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">a\\in A</annotation></semantics></math></span></span> such that <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mi>b</mi><mo>=</mo><mi>b</mi><mi>a</mi></mrow><annotation encoding=\"application/x-tex\">ab=ba</annotation></semantics></math></span></span> for every <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b</mi><mo>∈</mo><mi>B</mi></mrow><annotation encoding=\"application/x-tex\">b\\in B</annotation></semantics></math></span></span>.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0749\">Stacks 0749 · numbered source and proof</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/brauer/#tag-0749\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#G000306\">Open shared record</a></p></article>","G000310":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Unital associative algebras over a specified field · construction · <code>G000310</code></p><h3>Degree of a central simple algebra</h3><p>For a finite central simple <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">A</annotation></semantics></math></span></span> the degree is the unique positive integer <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow><annotation encoding=\"application/x-tex\">d</annotation></semantics></math></span></span> with <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">[</mo><mi>A</mi><mo>:</mo><mi>k</mi><mo stretchy=\"false\">]</mo><mo>=</mo><msup><mi>d</mi><mn>2</mn></msup></mrow><annotation encoding=\"application/x-tex\">[A:k]=d^2</annotation></semantics></math></span></span>. It is the matrix size over any splitting field.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0753\">Stacks 0753 · numbered source and proof · Stacks 0753 · degree following (6)</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/brauer/#tag-0753\">Index</a> · <a href=\"https://www.jmilne.org/math/CourseNotes/CFT.pdf#page=140\">J. S. Milne, Class Field Theory, IV, Proposition 2.15 and Corollary 2.16</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#G000310\">Open shared record</a></p></article>","G000307":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Possibly noncommutative unital rings · construction · <code>G000307</code></p><h3>Full matrix ring</h3><p>For <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>≥</mo><mn>1</mn></mrow><annotation encoding=\"application/x-tex\">n\\ge1</annotation></semantics></math></span></span>, <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>M</mi><mi>n</mi></msub><mo stretchy=\"false\">(</mo><mi>R</mi><mo stretchy=\"false\">)</mo></mrow><annotation encoding=\"application/x-tex\">M_n(R)</annotation></semantics></math></span></span> consists of square matrices over <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span></span> with ordinary matrix multiplication.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/074D\">Stacks 074D · numbered source and proof</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/brauer/#tag-074D\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#G000307\">Open shared record</a></p></article>","G000303":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Unital associative algebras over a specified field · construction · <code>G000303</code></p><h3>Opposite algebra</h3><p>The algebra <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>A</mi><mrow><mi mathvariant=\"normal\">o</mi><mi mathvariant=\"normal\">p</mi></mrow></msup></mrow><annotation encoding=\"application/x-tex\">A^{\\mathrm{op}}</annotation></semantics></math></span></span> has the same vector space and unit as <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">A</annotation></semantics></math></span></span>; its product of <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mo separator=\"true\">,</mo><mi>b</mi></mrow><annotation encoding=\"application/x-tex\">a,b</annotation></semantics></math></span></span> is <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b</mi><mi>a</mi></mrow><annotation encoding=\"application/x-tex\">ba</annotation></semantics></math></span></span> in <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A</mi></mrow><annotation encoding=\"application/x-tex\">A</annotation></semantics></math></span></span>.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0743\">Stacks 0743 · numbered source and proof · Stacks 0743 · opposite multiplication</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/brauer/#tag-0743\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#G000303\">Open shared record</a></p></article>","G000304":"<article class=\"algebra-definition atlas-panel\"><p class=\"property-context\">Possibly noncommutative unital rings · construction · <code>G000304</code></p><h3>Specified right ideal</h3><p>A right ideal <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi></mrow><annotation encoding=\"application/x-tex\">I</annotation></semantics></math></span></span> of a unital ring <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">R</annotation></semantics></math></span></span> is an additive subgroup stable under <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi><mo>↦</mo><mi>x</mi><mi>r</mi></mrow><annotation encoding=\"application/x-tex\">x\\mapsto xr</annotation></semantics></math></span></span> for all <span class=\"atlas-math\"><span class=\"katex\"><math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi><mo>∈</mo><mi>R</mi></mrow><annotation encoding=\"application/x-tex\">r\\in R</annotation></semantics></math></span></span>.</p><p class=\"property-references\"><a href=\"https://stacks.math.columbia.edu/tag/0745\">Stacks 0745 · numbered source and proof</a> <a class=\"algebra-index-ref\" href=\"../topologies/database/stacks/brauer/#tag-0745\">Index</a></p><p class=\"algebra-links\"><a href=\"../topologies/database/#G000304\">Open shared record</a></p></article>"};
